import{_ as t,a as n,b as o,c as i,d as s,e as r,f as a,g as l}from"./chunks/postman-environment-variables.CdIxqXJb.js";import{_ as p,o as g,c,ai as u}from"./chunks/framework.Ci0kozOl.js";const I=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/api/configuration.md","filePath":"3.0/api/configuration.md","lastUpdated":1786019473000}'),m={name:"3.0/api/configuration.md"};function d(h,e,f,P,_,y){return g(),c("div",null,[...e[0]||(e[0]=[u('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Before you can call the API, you need credentials. This page walks you through creating an API key in the admin panel and setting up Postman so you can send your first request in minutes.</p><h2 id="creating-api-credentials" tabindex="-1">Creating API Credentials <a class="header-anchor" href="#creating-api-credentials" aria-label="Permalink to &quot;Creating API Credentials&quot;">​</a></h2><p>UnoPim allows you to generate API credentials that control access to the platform through integrations. The process includes setting up API keys, configuring permissions, assigning users, and generating secret keys.</p><p>Follow these steps in the admin panel:</p><ol><li><strong>Navigate to the Integrations Tab</strong>: <ul><li>Go to <strong>Configuration</strong> -&gt; <strong>Integrations</strong> in the UnoPim admin panel.</li></ul></li></ol><p><img src="'+t+'" alt="Configuration Integrations tab"></p><ol start="2"><li><p><strong>Click on Create</strong>:</p><ul><li>Under the API Keys section, click the <strong>Create</strong> button to start the process of creating a new API key.</li></ul></li><li><p><strong>General Section</strong>:</p><ul><li>In the <strong>General</strong> Section, provide the following details: <ul><li><strong>Name</strong>: Enter a unique name for the API key.</li><li><strong>Assign User</strong>: Choose the user who will be assigned to this API key.</li></ul></li></ul><p><img src="'+n+'" alt="API key General section"></p></li><li><p><strong>Access Control</strong>:</p><ul><li><p>Navigate to the <strong>Access Control</strong> Section, where you&#39;ll configure permissions for the API key.</p></li><li><p><strong>Permissions Field</strong>: You&#39;ll see two options for setting permissions:</p><ol><li><strong>All</strong>: Grants full access to the API key across all features.</li><li><strong>Custom</strong>: Allows you to define specific permissions.</li></ol><p>If you select <strong>Custom</strong>, the following options will appear:</p><ul><li><strong>Settings Permissions</strong>: Use checkboxes to select which settings the API key can access.</li><li><strong>Catalog Permissions</strong>: Similarly, choose catalog-related permissions using checkboxes.</li></ul></li></ul></li><li><p><strong>Save and Activate</strong>:</p><ul><li>After filling out the necessary details and selecting permissions, click <strong>Save</strong> to generate the API credentials.</li></ul><p><img src="'+o+'" alt="Save API credentials"></p></li><li><p><strong>Generate Secret Key</strong>:</p><ul><li>Once saved, a <strong>Generate Secret Key</strong> button will appear.</li><li>Click on this button to display the <strong>Client ID</strong> and <strong>Secret Key</strong>.</li><li>These credentials will be used to access UnoPim&#39;s APIs.</li></ul><p><img src="'+i+'" alt="Generate Secret Key button"></p><p><img src="'+s+'" alt="Client ID and Secret Key"></p></li></ol><div class="tip custom-block"><p class="custom-block-title">Re-Generate Secret Key</p><p>After generating the secret key, a <strong>Re-Generate Secret Key</strong> button will be available. Use this button to regenerate the secret key if needed.</p></div><p>For more detailed reference, you can consult the UnoPim <strong>User Guide</strong> <a href="https://docs.unopim.com/1.0/configuration/integration.html" target="_blank" rel="noreferrer">here</a>.</p><h2 id="set-up-postman" tabindex="-1">Set up Postman <a class="header-anchor" href="#set-up-postman" aria-label="Permalink to &quot;Set up Postman&quot;">​</a></h2><p>UnoPim provides a Postman collection and environment to simplify API testing and exploration. Here is how to get them running:</p><ol><li><p><strong>Download Postman</strong>:</p><ul><li>If you haven&#39;t already, download and install the <strong>Postman</strong> application from the <a href="https://www.postman.com/downloads/" target="_blank" rel="noreferrer">official website</a>.</li></ul></li><li><p><strong>Download the required files</strong>:</p><ul><li>Download the following files to your system: <ul><li><p><a href="https://www.postman.com/unopim/unopim-apis/collection/kzy03uh/official-unopim-apis" target="_blank" rel="noreferrer">The Postman collection</a></p></li><li><p><a href="../../postman_collection.json">Download collection file</a></p></li></ul></li></ul><p><img src="'+r+'" alt="Postman collection export"></p><ul><li><p><a href="https://www.postman.com/unopim/unopim-apis/environment/37137259-33153010-2118-486f-bafe-2ed0b75ad39d" target="_blank" rel="noreferrer">A pre-configured Postman environment</a></p></li><li><p><a href="../../postman_environment.json">Download environment file</a></p></li></ul><p><img src="'+a+'" alt="Postman environment export"></p></li><li><p><strong>Import into Postman</strong>:</p><ul><li>Open Postman and use the <strong>Import</strong> button to add both the collection and environment files.</li></ul></li><li><p><strong>Select Environment</strong>:</p><ul><li>Once the environment is imported, select the <strong>UnoPim API</strong> environment from the environment dropdown menu.</li><li>Set the <strong>Environment</strong> variables, including the <strong>username</strong>, <strong>password</strong>, <strong>clientId</strong>, <strong>secret</strong>, and the <strong>URL</strong> of the application.</li></ul><p><img src="'+l+'" alt="Postman environment variables"></p></li><li><p><strong>Send a Request</strong>:</p><ul><li>Now you can send your first request using the pre-configured Postman collection to interact with UnoPim APIs.</li></ul></li></ol>',13)])])}const A=p(m,[["render",d]]);export{I as __pageData,A as default};
